<template>
  <section class="m-collection" :data-mobile-view="viewId">
    <header v-if="!isBlank" class="m-collection-heading"><div><h1>{{ title }}</h1><p>{{ items.length }} {{ items.length === 1 ? singularLabel : countLabel }}</p></div><button v-if="createLabel && !isBlank" type="button" class="m-primary m-create" @click="$emit('create')"><i class="fas fa-plus" aria-hidden="true"></i>{{ createLabel }}</button></header>
    <label v-if="!isBlank" class="m-search"><i class="fas fa-search" aria-hidden="true"></i><input :value="search" :placeholder="'Search ' + countLabel" :aria-label="'Search ' + countLabel" @input="$emit('update:search', $event.target.value)" /></label>
    <div v-if="tabs.length" class="m-tabs" role="tablist" :aria-label="title + ' views'"><button v-for="tab in tabs" :key="tab.id ?? tab.value" role="tab" type="button" :aria-selected="active === (tab.id ?? tab.value)" @click="$emit('tab', tab.id ?? tab.value)">{{ tab.label || tab.name }}<small v-if="tab.count != null">{{ tab.count }}</small></button></div>
    <div v-if="$slots.filters" class="m-filters"><slot name="filters" /></div>
    <details v-if="$slots.actions && !isBlank" class="m-options"><summary><i class="fas fa-sliders-h" aria-hidden="true"></i>Filter, sort & actions</summary><div class="m-options-content"><slot name="actions" /></div></details>
    <div v-if="loading" class="m-loading" role="status">Loading {{ countLabel }}…</div>
    <div v-else-if="!items.length" class="m-empty"><i :class="icon" aria-hidden="true"></i><h2>{{ search ? 'No matches' : 'No ' + countLabel + ' yet' }}</h2><p>{{ search ? 'Try a different search or clear the filters.' : (emptyText || (createLabel ? 'Create your first ' + singularLabel + ' to see it here.' : 'Nothing to show yet.')) }}</p><button v-if="search" type="button" @click="$emit('update:search', '')">Clear search</button><button v-else-if="createLabel" type="button" class="m-primary" @click="$emit('create')">{{ createLabel }}</button><slot name="empty" /></div>
    <div v-else class="m-records">
      <article v-for="item in items" :key="item.id || item.name" class="m-record" :class="{ selected: String(selectedId) === String(item.id) }" :data-record-id="item.id">
        <button type="button" class="m-record-open" @click.stop="$emit('select', item)"><span class="m-record-icon"><img v-if="item.avatar || item.thumbnail" :src="item.avatar || item.thumbnail" alt="" /><i v-else :class="item.icon?.includes(' ') ? item.icon : icon" aria-hidden="true"></i></span><span class="m-record-copy"><strong>{{ item[titleKey] || item.name || item.title || item.workflowName || item.agentName || item.content || 'Untitled' }}</strong><span>{{ item[descriptionKey] || item.description || item.tagline || item.content || item.category || '' }}</span><small v-if="item.category || item.updated_at || item.created_at">{{ item.category || date(item.updated_at || item.created_at) }}</small></span><span class="m-record-end"><small v-if="item.status || item.memory_type || item.type" class="m-status">{{ item.status || item.memory_type || item.type }}</small><i class="fas fa-chevron-right" aria-hidden="true"></i></span></button>
        <div v-if="$slots.item" class="m-record-actions"><slot name="item" :item="item" /></div>
      </article>
    </div>
    <slot name="footer" />
  </section>
</template>
<script setup>
import { computed } from 'vue';
const props = defineProps({viewId:String,title:String,countLabel:{type:String,default:'items'},items:{type:Array,default:()=>[]},search:{type:String,default:''},tabs:{type:Array,default:()=>[]},active:[String,Number],selectedId:[String,Number],createLabel:String,emptyText:String,loading:Boolean,icon:{type:String,default:'fas fa-cube'},titleKey:{type:String,default:'name'},descriptionKey:{type:String,default:'description'}});
defineEmits(['update:search','create','select','tab']);
const singularLabel = computed(() => ({memories:'memory',executions:'execution',datasets:'dataset',plugins:'plugin',agents:'agent',tools:'tool',widgets:'widget',workflows:'workflow',skills:'skill',goals:'goal',assets:'asset'})[props.countLabel] || props.countLabel.replace(/s$/, ''));
// A list with nothing in it and no query has nothing to search, filter or
// create from twice: the empty state carries the one create action.
const isBlank = computed(() => !props.loading && !props.items.length && !props.search);
const date=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleDateString();};
</script>
<style scoped>
section,header,label,article,button,input,span,div{box-sizing:border-box}
.m-collection{display:flex;flex-direction:column;gap:14px;width:100%;min-width:0;box-sizing:border-box;padding:18px 15px 28px;flex:1;min-height:0;overflow:auto;background:var(--color-background);color:var(--color-text)}
.m-collection-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.m-collection h1{font-size:23px;line-height:1.1;letter-spacing:-.035em;font-weight:600;margin:0}.m-collection-heading p{font-size:12px;line-height:1.5;color:var(--color-text-muted);margin:6px 0 0}.m-create{flex-shrink:0}.m-primary{background:var(--color-green)!important;color:var(--color-background)!important;border:1px solid transparent!important;font-weight:600!important}.m-collection button{font-family:inherit;cursor:pointer;min-height:44px}.m-create,.m-empty button{display:flex;align-items:center;justify-content:center;gap:7px;border-radius:10px;padding:10px 14px;font-size:14px}.m-search{width:100%;min-width:0;display:flex;align-items:center;gap:10px;border:1px solid var(--terminal-border-color);border-radius:11px;background:var(--color-darker-0);padding:0 12px;min-height:48px;flex-shrink:0}.m-search i{color:var(--color-text-muted);font-size:14px}.m-search input{background:none;border:0;outline-offset:2px;color:var(--color-text);height:44px;min-width:0;width:100%;font-size:16px;padding:0}.m-tabs{display:flex;gap:6px;overflow-x:auto;flex-shrink:0;scrollbar-width:none;margin-right:-15px;padding-right:15px;-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 28px),transparent)}.m-tabs button{display:flex;align-items:center;gap:6px;white-space:nowrap;border:1px solid var(--terminal-border-color);border-radius:20px;background:transparent;color:var(--color-text-muted);font-size:13px;padding:9px 14px;flex-shrink:0}.m-tabs button[aria-selected=true]{background:color-mix(in srgb,var(--color-green) 10%,transparent);color:var(--color-green);border-color:color-mix(in srgb,var(--color-green) 30%,transparent)}.m-tabs small{font-size:11px;opacity:.75}.m-options{border:1px solid var(--terminal-border-color);border-radius:10px;background:var(--color-darker-0);flex-shrink:0}.m-options summary{display:flex;gap:8px;align-items:center;cursor:pointer;min-height:44px;padding:0 12px;font-size:13px;color:var(--color-text-muted)}.m-options-content{padding:12px;display:flex;flex-wrap:wrap;gap:8px;border-top:1px solid var(--terminal-border-color)}.m-options-content :deep(button){min-height:44px}.m-records{display:flex;flex-direction:column;gap:10px}.m-record{border:1px solid var(--terminal-border-color);background:var(--color-darker-0);border-radius:13px;min-width:0}.m-record.selected{border-color:color-mix(in srgb,var(--color-green) 35%,transparent)}.m-record-open{display:flex;align-items:center;gap:11px;width:100%;border:0;background:none;color:var(--color-text);text-align:left;padding:15px 12px;box-sizing:border-box}.m-record-icon{display:grid;place-items:center;flex:none;width:38px;height:38px;border:1px solid var(--terminal-border-color);border-radius:11px;color:var(--color-green);background:var(--color-darker-0);overflow:hidden}.m-record-icon img{width:100%;height:100%;object-fit:cover}.m-record-copy{flex:1;min-width:0}.m-record-copy strong{display:block;font-size:14px;line-height:1.4;font-weight:500;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.m-record-copy>span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12px;line-height:1.55;color:var(--color-text-muted);margin-top:5px;overflow-wrap:anywhere}.m-record-copy>small{display:block;font-size:11px;color:var(--color-text-muted);margin-top:8px}.m-record-end{display:flex;flex-direction:row;align-items:center;gap:10px;max-width:120px;flex:none;color:var(--color-text-muted);font-size:11px}.m-status{font-size:11px;line-height:1.4;border-radius:6px;padding:3px 7px;white-space:nowrap;background:color-mix(in srgb,var(--color-green) 9%,transparent);color:var(--color-green);overflow-wrap:anywhere}.m-record-actions{border-top:1px solid var(--terminal-border-color);padding:6px 10px;display:flex;gap:5px;flex-wrap:wrap}.m-record-actions :deep(button){border:0;background:none;color:var(--color-text-muted);font:12px inherit;padding:5px 9px;min-height:44px}.m-empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:260px}.m-empty p{margin:0;max-width:280px}.m-empty,.m-loading{padding:32px 8px;text-align:center;color:var(--color-text-muted);font-size:13px;line-height:1.7}.m-empty>i{font-size:28px;color:var(--color-green)}.m-empty h2{font-size:20px;color:var(--color-text)}.m-empty button{margin:14px auto}.m-filters{min-width:0;flex-shrink:0}.m-filters :deep(.view-tabs){max-width:100%;overflow:auto}.m-record-open:focus-visible,.m-tabs button:focus-visible{outline:2px solid var(--color-green);outline-offset:2px}
</style>
